template <typename InputIt, typename Predicate>
InputIt find_if_custom(InputIt first, InputIt last, Predicate p) {
    while (first != last) {
        if (p(*first)) return first;
        ++first;
    }
    return last;
}

// Example usage demonstrating deduction
std::vector<int> data = {1, 4, 9, 16};

auto is_odd = [](int n) { return n % 2 != 0; };

// InputIt deduced as std::vector<int>::iterator
// Predicate deduced as the specific lambda type
auto result = find_if_custom(data.begin(), data.end(), is_odd);

// result points to 1
// find_if_custom<std::vector<int>::iterator, LambdaType>(...) deduced
std::optional<int> res_val = result != data.end() ? *result : std::nullopt;
